"\"\"Tests for OpenTelemetry metrics — RED first (fail until implementation lands).\"\"\n\nfrom datetime import datetime, timedelta, timezone\nfrom unittest.mock import AsyncMock, patch\n\nimport pytest\nimport pytest_asyncio\nfrom opentelemetry.sdk.metrics import MeterProvider\nfrom opentelemetry.sdk.metrics.export import InMemoryMetricReader\n\nfrom scheduler.metrics import create_metrics\nfrom scheduler.store import Store\n\n\n@pytest_asyncio.fixture\nasync def store():\n    s = Store(\"sqlite+aiosqlite:///:memory:\")\n    await s.init()\n    yield s\n    await s.dispose()\n\n\n@pytest_asyncio.fixture\ndef metrics_reader():\n    \"\"\"In-memory metric reader for test assertions (the agent-host pattern).\"\"\"\n    return InMemoryMetricReader()\n\n\n@pytest_asyncio.fixture\ndef metrics_sink(metrics_reader):\n    \"\"\"Metrics sink with an in-memory reader for assertions.\"\"\"\n    provider = MeterProvider(metric_readers=[metrics_reader])\n    return create_metrics(enabled=True, meter_provider=provider)\n\n\n@pytest.mark.asyncio\nasync def test_fire_success_increments_fires_total_spawned(store, metrics_reader, metrics_sink):\n    t = await store.create_task(\n        title=\"t\", prompt=\"p\", cron=\"* * * * *\", timezone_=\"UTC\", owner=\"alice\", enabled=True\n    )\n    # Simulate a successful fire\n    run_id = await store.start_run(t.id)\n    await store.finish_run(run_id, conversation_id=\"conv-123\", status=\"spawned\", error=None)\n    metrics_sink.record_fire(status=\"spawned\")\n\n    metrics = metrics_reader.get_metrics_data()\n    c = next(m for m in metrics.resource_metrics[0].scope_metrics[0].metrics if m.name == \"scheduler_fires_total\")\n    assert c.data.data_points[0].value == 1\n    assert c.data.data_points[0].attributes[\"status\"] == \"spawned\"\n\n\n@pytest.mark.asyncio\nasync def test_fire_failure_increments_fires_total_failed(store, metrics_reader, metrics_sink):\n    t = await store.create_task(\n        title=\"t\", prompt=\"p\", cron=\"* * * * *\", timezone_=\"UTC\", owner=\"alice\", enabled=True\n    )\n    run_id = await store.start_run(t.id)\n    await store.finish_run(run_id, conversation_id=None, status=\"failed\", error=\"spawn error\")\n    metrics_sink.record_fire(status=\"failed\")\n\n    metrics = metrics_reader.get_metrics_data()\n    c = next(m for m in metrics.resource_metrics[0].scope_metrics[0].metrics if m.name == \"scheduler_fires_total\")\n    assert c.data.data_points[0].value == 1\n    assert c.data.data_points[0].attributes[\"status\"] == \"failed\"\n\n\n@pytest.mark.asyncio\nasync def test_spawn_duration_histogram(metrics_reader, metrics_sink):\n    metrics_sink.record_spawn_duration(123.45)\n    metrics_sink.record_spawn_duration(67.89)\n\n    metrics = metrics_reader.get_metrics_data()\n    h = next(m for m in metrics.resource_metrics[0].scope_metrics[0].metrics if m.name == \"scheduler_spawn_duration_ms\")\n    assert h.data.data_points[0].count == 2\n    assert h.data.data_points[0].sum == pytest.approx(191.34, abs=0.01)\n\n\n@pytest.mark.asyncio\nasync def test_tick_duration_histogram(metrics_reader, metrics_sink):\n    metrics_sink.record_tick_duration(50.0)\n    metrics_sink.record_tick_duration(75.0)\n\n    metrics = metrics_reader.get_metrics_data()\n    h = next(m for m in metrics.resource_metrics[0].scope_metrics[0].metrics if m.name == \"scheduler_tick_duration_ms\")\n    assert h.data.data_points[0].count == 2\n    assert h.data.data_points[0].sum == 125.0\n\n\n@pytest.mark.asyncio\nasync def test_tick_with_no_due_tasks_still_increments_ticks_total(store, metrics_reader, metrics_sink):\n    \"\"\"CRITICAL: a tick with NO due tasks must still increment scheduler_ticks_total — the dead-loop detector.\"\"\"\n    # No due tasks in the store (empty or all future)\n    now = datetime.now(timezone.utc)\n    future = now + timedelta(hours=1)\n    await store.create_task(\n        title=\"later\", prompt=\"p\", cron=\"* * * * *\", timezone_=\"UTC\", owner=\"a\", enabled=True\n    )\n    # Manually set next_run_at to future\n    t = await store.list_tasks(owner=\"a\")\n    await store.reschedule(t[0].id, last_run_at=now, next_run_at=future)\n\n    # Tick with no due tasks\n    due = await store.claim_due(now)\n    assert len(due) == 0\n\n    # The scheduler loop would call this even when due == []\n    metrics_sink.record_tick(outcome=\"ok\")\n\n    metrics = metrics_reader.get_metrics_data()\n    c = next(m for m in metrics.resource_metrics[0].scope_metrics[0].metrics if m.name == \"scheduler_ticks_total\")\n    assert c.data.data_points[0].value == 1\n    assert c.data.data_points[0].attributes[\"outcome\"] == \"ok\"\n\n\n@pytest.mark.asyncio\nasync def test_claim_lag_histogram(store, metrics_reader, metrics_sink):\n    \"\"\"Verify claim lag is recorded for overdue tasks.\"\"\"\n    now = datetime.now(timezone.utc)\n    past = now - timedelta(seconds=30)  # 30s overdue\n    t = await store.create_task(\n        title=\"overdue\", prompt=\"p\", cron=\"* * * * *\", timezone_=\"UTC\", owner=\"alice\", enabled=True\n    )\n    await store.reschedule(t.id, last_run_at=past - timedelta(minutes=1), next_run_at=past)\n\n    due = await store.claim_due(now)\n    assert len(due) == 1\n    # The store attaches _claim_lag_ms as a transient attribute\n    if hasattr(due[0], \"_claim_lag_ms\"):\n        metrics_sink.record_claim_lag(due[0]._claim_lag_ms)\n\n        metrics = metrics_reader.get_metrics_data()\n        h = next(\n            m for m in metrics.resource_metrics[0].scope_metrics[0].metrics if m.name == \"scheduler_claim_lag_ms\"\n        )\n        # Should be ~30,000ms (30 seconds)\n        assert h.data.data_points[0].count == 1\n        assert 29000 < h.data.data_points[0].sum < 31000\n\n\n@pytest.mark.asyncio\nasync def test_retention_sweep_deletes_old_runs(store, metrics_reader, metrics_sink):\n    \"\"\"Verify prune_old_runs deletes runs older than retention_days and increments the counter.\"\"\"\n    t = await store.create_task(\n        title=\"t\", prompt=\"p\", cron=\"* * * * *\", timezone_=\"UTC\", owner=\"alice\", enabled=True\n    )\n\n    now = datetime.now(timezone.utc)\n    old = now - timedelta(days=100)  # older than 90-day default\n    recent = now - timedelta(days=30)  # within 90 days\n\n    # Create 2 old runs, 1 recent\n    run1 = await store.start_run(t.id)\n    await store.finish_run(run1, conversation_id=\"c1\", status=\"spawned\", error=None)\n    run2 = await store.start_run(t.id)\n    await store.finish_run(run2, conversation_id=\"c2\", status=\"spawned\", error=None)\n    run3 = await store.start_run(t.id)\n    await store.finish_run(run3, conversation_id=\"c3\", status=\"spawned\", error=None)\n\n    # Manually backdate run1 and run2 to be old\n    await store._execute(\n        f\"UPDATE runs SET created_at = '{old.isoformat()}' WHERE id IN ('{run1}', '{run2}')\"\n    )\n\n    deleted = await store.prune_old_runs(retention_days=90, now=now, owner=None)\n    assert deleted == 2\n    metrics_sink.record_runs_pruned(deleted)\n\n    runs = await store.list_runs(t.id, owner=\"alice\")\n    assert len(runs) == 1  # only the recent one remains\n\n    metrics = metrics_reader.get_metrics_data()\n    c = next(\n        m for m in metrics.resource_metrics[0].scope_metrics[0].metrics if m.name == \"scheduler_runs_pruned_total\"\n    )\n    assert c.data.data_points[0].value == 2\n\n\n@pytest.mark.asyncio\nasync def test_retention_sweep_disabled_when_zero(store, metrics_reader, metrics_sink):\n    \"\"\"Verify retention_days=0 disables the sweep (no DELETE).\"\"\"\n    t = await store.create_task(\n        title=\"t\", prompt=\"p\", cron=\"* * * * *\", timezone_=\"UTC\", owner=\"alice\", enabled=True\n    )\n    run_id = await store.start_run(t.id)\n    await store.finish_run(run_id, conversation_id=\"c1\", status=\"spawned\", error=None)\n\n    now = datetime.now(timezone.utc)\n    deleted = await store.prune_old_runs(retention_days=0, now=now, owner=None)\n    assert deleted == 0  # nothing deleted\n\n    runs = await store.list_runs(t.id, owner=\"alice\")\n    assert len(runs) == 1  # the run still exists\n"